def parse_docstring_tags(thing):
    """Parse a Python docstring, or the docstring found on `thing`.

    :return: a list of tags.
    """
    docstring = thing.__doc__ or ''
    if not docstring:
        return []

    lines = docstring.splitlines()
    if not lines:
        return []

    tags = []
    for line in lines:
        if line.startswith('@'):
            tags.append(line[1:].strip())

    return tags


